<template><div><Stage2View v-if="stage2WebUiEnabled && !review"/><UsabilityView v-else-if="usabilityEnabled" :review="$route.name==='s1-reviews'"/><Card v-else><h2>{{review?'商品审核':'商品监管'}}</h2><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><Input v-model="search" maxlength="60" placeholder="商品名称" style="width:240px"/><Input v-model="targetStore" placeholder="店铺编号（可选）" style="width:220px"/><Select v-if="!review" v-model="status" clearable placeholder="审核状态" style="width:160px"><Option v-for="s in ['DRAFT','SUBMITTED','APPROVED','REJECTED']" :key="s" :value="s">{{label(s)}}</Option></Select><Select v-if="!review" v-model="marketStatus" clearable placeholder="上架状态" style="width:140px"><Option value="UPPER">已上架</Option><Option value="DOWN">已下架</Option></Select><Select v-if="!review" v-model="stockState" clearable placeholder="库存状态" style="width:140px"><Option value="IN_STOCK">有可售库存</Option><Option value="OUT_OF_STOCK">缺货</Option><Option value="INCOMPLETE">SKU资料不完整</Option></Select><Select v-if="!review" v-model="forced" clearable placeholder="监管状态" style="width:140px"><Option value="true">监管下架</Option><Option value="false">未受管制</Option></Select><Button @click="page=1;reload()">查询</Button></div><Table :columns="columns" :data="records" :loading="loading" no-data-text="暂无商品"><template slot="status" slot-scope="{row}">{{label(row.reviewStatus)}} / {{label(row.marketStatus)}}<Tag v-if="row.forcedOff" color="red">强制下架</Tag></template><template slot="price" slot-scope="{row}">{{money(row.priceCent)}}</template><template slot="action" slot-scope="{row}"><Button size="small" @click="open(row)">商品详情</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" title="商品内容、库存与监管" width="85"><template v-if="selected"><EligibilityCard :value="selected.goods.eligibility"/><div class="s1-toolbar"><template v-if="selected.goods.reviewStatus==='SUBMITTED'&&can('goods.review')"><Button type="primary" :disabled="busy||pending" @click="command('approve')">批准内容版本 {{selected.goods.contentVersion}}</Button><Button type="error" :disabled="busy||pending" @click="command('reject')">驳回</Button></template><Button v-if="can('goods.supervise')" :disabled="busy||pending" type="warning" @click="command(selected.goods.forcedOff?'release':'force-off')">{{selected.goods.forcedOff?'解除管制并保持下架':'强制下架'}}</Button></div><RecordDetail :value="selected" @preview="preview"/></template></Drawer></Card></div></template>
<script>import Stage2View from '../p0-stage2/GoodsList';import {stage2WebUiEnabled} from '../p0-stage2/enabled';import {usabilityEntry} from './usability/enabled';import {leaveGuard} from './usability/entry';import UiView from './usability/GoodsList';import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import RecordDetail from './RecordDetail';import EligibilityCard from './EligibilityCard';const LegacyView = {props:{review:Boolean},mixins:[pageMixin],components:{StatusPanel,RecordDetail,EligibilityCard},data:()=>({show:false,search:'',targetStore:'',status:'',marketStatus:'',stockState:'',forced:'',columns:[{title:'商品',key:'name',minWidth:180},{title:'编号',key:'id',minWidth:180},{title:'店铺编号',key:'storeId',minWidth:180},{title:'价格',slot:'price',width:110},{title:'当前库存',key:'quantity',width:100},{title:'状态',slot:'status',minWidth:220},{title:'操作',slot:'action',width:120}]}),mounted(){if(this.usabilityEnabled||stage2WebUiEnabled)return;this.reload();},methods:{reload(){return this.load(this.review?'/goods/reviews':'/goods',{targetStore:this.targetStore||undefined,search:this.search||undefined,...(!this.review?{status:this.status||undefined,marketStatus:this.marketStatus||undefined,stockState:this.stockState||undefined,forced:this.forced||undefined}:{})});},async open(row){try{this.selected=await s1Read('/goods/'+row.id);this.show=true;}catch(e){this.error=e.message;}},async command(action){const g=this.selected.goods;const result=await this.reasonAction('/goods/'+g.id+'/'+action,{approve:'批准当前送审内容',reject:'驳回当前送审内容','force-off':'强制下架',release:'解除管制后商品仍保持下架'}[action],{expectedVersion:g.version,contentVersion:g.contentVersion});if(result){await this.open(g);await this.reload();}}}};LegacyView.mixins.push(usabilityEntry);LegacyView.computed={...LegacyView.computed,stage2WebUiEnabled:()=>stage2WebUiEnabled};LegacyView.components={...LegacyView.components,Stage2View,UsabilityView:UiView};LegacyView.beforeRouteLeave=leaveGuard;LegacyView.beforeRouteUpdate=leaveGuard;export default LegacyView;</script>
<style scoped>.s1-toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.ivu-page{margin-top:18px}</style>
